postgres"],"body":"\n select exists(select 1 from app.canonical_games game where game.id=p_game_id and game.state in(''verified'',''corrected'') and (select count(*) from app.card_scorelines scoreline where scoreline.canonical_game_id=game.id)=2)\n or exists(select 1 from app.device_failure_recoveries recovery where recovery.canonical_game_id=p_game_id and app.device_recovery_is_approved(recovery.id))\n or exists(select 1 from app.operational_game_forfeits forfeiture where forfeiture.canonical_game_id=p_game_id)\n","definition":"CREATE OR REPLACE FUNCTION app.game_is_authoritatively_resolved_v1(p_game_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\n select exists(select 1 from app.canonical_games game where game.id=p_game_id and game.state in(''verified'',''corrected'') and (select count(*) from app.card_scorelines scoreline where scoreline.canonical_game_id=game.id)=2)\n or exists(select 1 from app.device_failure_recoveries recovery where recovery.canonical_game_id=p_game_id and app.device_recovery_is_approved(recovery.id))\n or exists(select 1 from app.operational_game_forfeits forfeiture where forfeiture.canonical_game_id=p_game_id)\n$function$\n"},{"signature":"auth.jwt()","found":true,"owner":"supabase_auth_admin","prosecdef":false,"provolatile":"s","proconfig":null,"acl":["=X/supabase_auth_admin","postgres=X/supabase_auth_admin","supabase_auth_admin=X/supabase_auth_admin","dashboard_user=X/supabase_auth_admin"],"body":"\n  select \n    coalesce(\n        nullif(current_setting(''request.jwt.claim'', true), ''''),\n        nullif(current_setting(''request.jwt.claims'', true), '''')\n    )::jsonb\n","definition":"CREATE OR REPLACE FUNCTION auth.jwt()\n RETURNS jsonb\n LANGUAGE sql\n STABLE\nAS $function$\n  select \n    coalesce(\n        nullif(current_setting(''request.jwt.claim'', true), ''''),\n        nullif(current_setting(''request.jwt.claims'', true), '''')\n    )::jsonb\n$function$\n"}]'::jsonb then raise exception 'closeout_v21_current_helpers_mismatch';end if;end$pin$;
do $pin$declare actual jsonb;begin select jsonb_agg(to_jsonb(r))into actual from(select s.name,c.oid is not null as found,pg_get_userbyid(c.relowner)as owner,c.relrowsecurity as rls,c.relforcerowsecurity as force,to_jsonb(c.relacl)as acl,
