LETE RESTRICT",true,false,false],["canonical_games_id_tournament_id_event_id_key","UNIQUE (id, tournament_id, event_id)",true,false,false],["canonical_games_id_tournament_id_key","UNIQUE (id, tournament_id)",true,false,false],["canonical_games_margin_check","CHECK (((margin IS NULL) OR ((margin >= 1) AND (margin <= 121))))",true,false,false],["canonical_games_match_instance_check","CHECK ((match_instance > 0))",true,false,false],["canonical_games_pkey","PRIMARY KEY (id)",true,false,false],["canonical_games_round_id_tournament_id_event_id_fkey","FOREIGN KEY (round_id, tournament_id, event_id) REFERENCES app.rounds(id, tournament_id, event_id) ON DELETE RESTRICT",true,false,false],["canonical_games_side_a_participant_id_event_id_tournament__fkey","FOREIGN KEY (side_a_participant_id, event_id, tournament_id) REFERENCES app.event_participants(id, event_id, tournament_id) ON DELETE RESTRICT",true,false,false],["canonical_games_side_a_table_seat_snapshot_check","CHECK ((side_a_table_seat_snapshot ~ ''^[A-Za-z0-9]+-[0-9]+$''::text))",true,false,false],["canonical_games_side_b_participant_id_event_id_tournament__fkey","FOREIGN KEY (side_b_participant_id, event_id, tournament_id) REFERENCES app.event_participants(id, event_id, tournament_id) ON DELETE RESTRICT",true,false,false],["canonical_games_side_b_table_seat_snapshot_check","CHECK ((side_b_table_seat_snapshot ~ ''^[A-Za-z0-9]+-[0-9]+$''::text))",true,false,false],["canonical_games_state_check","CHECK ((state = ANY (ARRAY[''pending''::text, ''submitted''::text, ''mismatch''::text, ''confirmation_pending''::text, ''verified''::text, ''corrected''::text])))",true,false,false],["canonical_games_version_check","CHECK ((version > 0))",true,false,false],["canonical_games_winner_side_check","CHECK ((winner_side = ANY (ARRAY[''a''::text, ''b''::text])))",true,false,false],["game_state_requires_two_submissions","TRIGGER DEFERRABLE INITIALLY DEFERRED",true,true,true]],"triggers":[["a0_joint_source_guard_v1","O","CREATE TRIGGER a0_joint_source_guard_v1 BEFORE INSERT OR DELETE OR UPDATE ON app.canonical_games FOR EACH ROW EXECUTE FUNCTION app.guard_multi_event_joint_source_v1()","CREATE OR REPLACE FUNCTION app.guard_multi_event_joint_source_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare t uuid;begin\n for t in select distinct x from unnest(array[(to_jsonb(new)->>''tournament_id'')::uuid,(to_jsonb(old)->>''tournament_id'')::uuid])x where x is not null order by x loop\n  if not exists(select 1 from app.multi_event_finance_modes_v1 where tournament_id=t) then continue;end if;\n  if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(''multi-event-joint-source:''||t::text,0)) then raise exception ''joint_finalization_in_progress'';end if;\n  if exists(select 1 from app.multi_event_joint_finals_v1 where tournament_id=t) then raise exception ''joint_financially_closed'';end if;\n end loop;\n return case when tg_op=''DELETE'' then old else new end;\nend$function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["game_state_requires_two_submissions","O","CREATE CONSTRAINT TRIGGER game_state_requires_two_submissions AFTER INSERT OR UPDATE ON app.canonical_games DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.assert_two_submissions_before_verified()","CREATE OR REPLACE FUNCTION app.assert_two_submissions_before_verified()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n  perform app.revalidate_game(new.id);\n  return new;\nend; $function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["protect_published_schedule_game","O","CREATE TRIGGER protect_published_schedule_game BEFORE DELETE OR UPDATE ON app.canonical_games FOR EACH ROW EXECUTE FUNCTION app.protect_published_schedule_game()","CREATE OR REPLACE FUNCTION app.protect_published_schedule_game()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n  if exists(select 1 from app.event_schedule_games sg where sg.canonical_game_id=old.id) then\n    if tg_op=''DELETE'' then raise exception ''published schedule game is immutable'';end if;\n    if (new.tournament_id,new.event_id,new.round_id,new.match_instance) is distinct from\n       (old.tournament_id,old.event_id,old.round_id,old.match_instance) then raise exception ''published schedule identity is immutable'';end if;\n    if (new.side_a_participant_id,new.side_b_participant_id,new.side_a_table_seat_snapshot,new.side_b_table_seat_snapshot) is distinct from\n       (old.side_a_participant_id,old.side_b_participant_id,old.side_a_table_seat_snapshot,old.side_b_table_seat_snapshot)\n       and current_setting(''app.validated_schedule_amendment'',true) is distinct from ''on'' then\n      raise exception ''published schedule assignment is immutable'';\n    end if;\n  end if;\n  return case when tg_op=''DELETE'' then old else new end;\nend $function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["qualification_freeze_canonical_games","O","CREATE TRIGGER qualification_freeze_canonical_games BEFORE INSERT OR DELETE OR UPDATE ON app.canonical_games FOR EACH ROW EXECUTE FUNCTION app.block_finalized_qualification_mutation()","CREATE OR REPLACE FUNCTION app.block_finalized_qualification_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare v_event_id uuid;\nbegin\n  v_event_id := coalesce((to_jsonb(new)->>''event_id'')::uuid, (to_jsonb(old)->>''event_id'')::uuid);\n  if exists (select 1 from app.qualification_result_versions result where result.event_id = v_event_id) then\n    raise exception ''finalized qualification snapshot blocks event mutation'';\n  end if;\n  return case when tg_op = ''DELETE'' then old else new end;\nend;\n$function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["synthetic_canonical_change_guard_v1","O","CREATE TRIGGER synthetic_canonical_change_guard_v1 BEFORE UPDATE ON app.canonical_games FOR EACH ROW EXECUTE FUNCTION app.guard_synthetic_canonical_change_v1()","CREATE OR REPLACE FUNCTION app.guard_synthetic_canonical_change_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\r\ndeclare aid uuid;\r\nbegin\r\n if exists(select 1 from app.synthetic_paper_fixtures_v1 where event_id=new.event_id and tournament_id=new.tournament_id)\r\n and (new.state,new.version,new.winner_side,new.margin)is distinct from(old.state,old.version,old.winner_side,old.margin)then\r\n select id into aid from app.synthetic_paper_artifacts_v1 where game_id=new.id;\r\n if aid is null or current_setting(''app.synthetic_paper_artifact'',true)is distinct from aid::text then raise exception''synthetic_evidence_required'';end if;\r\n end if;return new;\r\nend$function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["synthetic_mixed_canonical_v1","O","CREATE TRIGGER synthetic_mixed_canonical_v1 BEFORE UPDATE ON app.canonical_games FOR EACH ROW WHEN (((((old.state IS DISTINCT FROM new.state) OR (old.version IS DISTINCT FROM new.version)) OR (old.winner_side IS DISTINCT FROM new.winner_side)) OR (old.margin IS DISTINCT FROM new.margin))) EXECUTE FUNCTION app.guard_synthetic_mixed_write_v1()","CREATE OR REPLACE FUNCTION app.guard_synthetic_mixed_write_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare m app.synthetic_mixed_games_v1%rowtype;a app.synthetic_mixed_artifacts_v1%rowtype;c app.synthetic_mixed_contexts_v1%rowtype;gid uuid;j jsonb:=to_jsonb(new);\nbegin\n gid:=case when tg_table_name=''canonical_games''then(j->>''id'')::uuid else(j->>''canonical_game_id'')::uuid end;\n select * into m from app.synthetic_mixed_games_v1 where game_id=gid;\n if not found then return new;end if;\n perform app.assert_synthetic_mixed_current_v1(m.tournament_id,m.event_id);\n if m.pairing=''DD''then\n if tg_table_name not in(