from a.payload->>''qualificationResultVersionId''\r\n   or new.request_payload->''expectedVersion''is distinct from a.payload->''expectedVersion''\r\n   or(select jsonb_agg(x-''evidenceNote''order by n)from jsonb_array_elements(new.series)with ordinality e(x,n))is distinct from a.payload->''series''\r\n   or exists(select 1 from jsonb_array_elements(new.series)with ordinality e(x,n)where x->>''evidenceNote''<>ref||'':''||n)\r\n   or position(''TEST ONLY SYNTHETIC:''in(new.request_payload->>''reason''))<>1 then raise exception''synthetic_event_evidence_mismatch'';end if;\r\n else\r\n  if new.action<>''closed''or new.scheduled_game_count is distinct from(a.payload->>''scheduledGames'')::integer or new.resolved_game_count is distinct from(a.payload->>''verifiedGames'')::integer or position(''TEST ONLY SYNTHETIC: ''||ref||'' ''in new.reason)<>1 or position(''TEST ONLY SYNTHETIC:''in new.reason)<>1 then raise exception''synthetic_event_evidence_mismatch'';end if;\r\n end if;return new;\r\nend$function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["event_play_closes_immutable","O","CREATE TRIGGER event_play_closes_immutable BEFORE DELETE OR UPDATE ON app.event_play_closes FOR EACH ROW EXECUTE FUNCTION app.reject_immutable_history()","CREATE OR REPLACE FUNCTION app.reject_immutable_history()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$ begin raise exception ''immutable history''; end; $function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["mixed_main_provenance_event_play_closes","O","CREATE TRIGGER mixed_main_provenance_event_play_closes AFTER INSERT ON app.event_play_closes FOR EACH ROW EXECUTE FUNCTION app.annotate_synthetic_mixed_main_row_v1()","CREATE OR REPLACE FUNCTION app.annotate_synthetic_mixed_main_row_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\r\ndeclare j jsonb:=to_jsonb(new);c app.synthetic_mixed_main_contexts_v1%rowtype;begin\r\n if not exists(select 1 from app.synthetic_mixed_finance_scopes_v1 where tournament_id=new.tournament_id)then return new;end if;\r\n -- Before guard already checked the current artifact. A qualification insert\r\n -- may itself change its reader; do not recompute that reader after writing.\r\n select * into c from app.synthetic_mixed_main_contexts_v1 where id::text=current_setting(''app.synthetic_mixed_main_context'',true)\r\n and tournament_id=new.tournament_id and backend_pid=pg_backend_pid()and transaction_id=txid_current();\r\n if not found or not app.synthetic_mixed_main_allowed_table_v1(c.action,tg_table_name)then raise exception''mixed_main_annotation_context_required'';end if;\r\n insert into app.synthetic_mixed_main_provenance_v1(tournament_id,event_id,entity_table,entity_id,operation_receipt_id,context_id,artifact_id,action,record_sha256)\r\n values(new.tournament_id,c.event_id,tg_table_name,(j->>''id'')::uuid,(j->>''operation_receipt_id'')::uuid,c.id,c.artifact_id,c.action,encode(extensions.digest(j::text,''sha256''),''hex''));\r\n return new;\r\nend$function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["synthetic_provenance_event_play_closes","O","CREATE TRIGGER synthetic_provenance_event_play_closes AFTER INSERT ON app.event_play_closes FOR EACH ROW EXECUTE FUNCTION app.annotate_synthetic_event_record_v1()","CREATE OR REPLACE FUNCTION app.annotate_synthetic_event_record_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\r\ndeclare j jsonb:=to_jsonb(new);eid uuid;aid uuid;r app.operation_receipts%rowtype;digest text;begin\r\n if j?''event_id''then eid:=(j->>''event_id'')::uuid;\r\n else if(select count(*)from app.synthetic_paper_fixtures_v1 where tournament_id=new.tournament_id)<>1 then return new;end if;select event_id into eid from app.synthetic_paper_fixtures_v1 where tournament_id=new.tournament_id;end if;\r\n if not exists(select 1 from app.synthetic_paper_fixtures_v1 w