1 where event_id=new.event_id) then raise exception ''playoff_domain_conflict'';end if;\n return new;\nend$function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["aa_event_settings_finance_backstop_v1","O","CREATE TRIGGER aa_event_settings_finance_backstop_v1 BEFORE INSERT ON app.standard_singles_settlement_final_versions FOR EACH ROW EXECUTE FUNCTION app.require_event_settings_finance_backstop_v1()","CREATE OR REPLACE FUNCTION app.require_event_settings_finance_backstop_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n -- A retained snapshot could hide a newly committed configured binding.\n if current_setting(''transaction_isolation'')<>''read committed''then raise exception''event_settings_finance_isolation_not_supported'';end if;\n perform 1 from app.tournaments where id=new.tournament_id for update nowait;\n if not found then raise exception''event_settings_finance_tournament_unavailable'';end if;\n if tg_table_name=''multi_event_joint_finals_v1''then\n  if exists(select 1 from app.event_settings_operational_bindings_v1 where tournament_id=new.tournament_id)then raise exception''event_settings_finance_integration_required'';end if;\n elsif exists(select 1 from app.event_settings_operational_bindings_v1 where tournament_id=new.tournament_id and event_id=new.event_id)then\n  raise exception''event_settings_finance_integration_required'';\n end if;\n return new;\nend$function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["aa_native_final_award_liability_v1","O","CREATE TRIGGER aa_native_final_award_liability_v1 BEFORE INSERT ON app.standard_singles_settlement_final_versions FOR EACH ROW EXECUTE FUNCTION app.require_no_native_final_award_liability_v1()","CREATE OR REPLACE FUNCTION app.require_no_native_final_award_liability_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n if current_setting(''transaction_isolation'')<>''read committed''then raise exception''native_final_award_isolation_not_supported'';end if;\n perform 1 from app.tournaments where id=new.tournament_id for update nowait;\n if tg_table_name=''multi_event_joint_finals_v1''then\n  if exists(select 1 from app.native_playoff_final_award_sets_v1 where tournament_id=new.tournament_id)then\n   raise exception''native_final_award_liability_exists'';end if;\n elsif exists(select 1 from app.native_playoff_final_award_sets_v1 where tournament_id=new.tournament_id and event_id=new.event_id)then\n  raise exception''native_final_award_liability_exists'';\n end if;\n return new;\nend$function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["aa_optional_final_liability_v2","O","CREATE TRIGGER aa_optional_final_liability_v2 BEFORE INSERT ON app.standard_singles_settlement_final_versions FOR EACH ROW EXECUTE FUNCTION app.guard_native_optional_final_liability_v2()","CREATE OR REPLACE FUNCTION app.guard_native_optional_final_liability_v2()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare current_source jsonb;current_count integer;p jsonb;\nbegin\n if current_setting(''transaction_isolation'')<>''read committed''then raise exception''optional_final_isolation_not_supported'';end if;\n perform 1 from app.tournaments where id=new.tournament_id for update nowait;\n if tg_table_name=''native_optional_final_award_sets_v2''then\n  if app.legacy_financial_liability_exists_v1(new.tournament_id,new.event_id)is distinct from false\n   or exists(select 1 from app.native_playoff_final_award_sets_v1 where tournament_id=new.tournament_id and event_id=new.event_id)\n  then raise exception''other_final_award_liability_exists'';end if;\n  current_source:=app.native_optional_final_award_source_v2(new.actor_id,new.tournament_id,new.event_id);\n  if current_source is null or current_source->>''status''is distinct from''source_available''\n   or current_source is distinct from new.source_capture or current_source->>''sourceDigest''is distinct from new.source_digest\n   or current_source#>>''{fundReview,id}''is distinct from new.fund_review_id::text\n   or current_source#>>''{fundSource,proposalRevisionId}''is distinct from new.proposal_revision_id::text\n   or current_source#>>''{fundSource,ownershipRevisionId}''is distinct from new.ownership_revision_id::text\n   or current_source#>>''{fundSource,recipientSource,playoff,qualificationResultVersionId}''is distinct from new.qualification_id::text\n   or(current_source#>>''{fundSource,funds,regularFundMinor}'')::numeric is distinct from new.regular_minor::numeric\n   or(current_source#>>''{fundSource,funds,qFundMinor}'')::numeric is distinct from new.q_minor::numeric\n   or(current_source#>>''{fundSource,funds,sideFundMinor}'')::numeric is distinct from new.side_minor::numeric\n  then raise exception''optional_final_source_changed'';end if;\n  current_count:=jsonb_array_length(current_source#>''{regularProjection,recipients}'');\n  for p in select value from jsonb_array_elements(current_source->''optionalPools'')loop current_count:=current_count+jsonb_array_length(p->''rows'');end loop;\n  if new.recipient_count is distinct from current_count then raise exception''optional_final_recipient_count_changed'';end if;\n elsif tg_table_name=''multi_event_joint_finals_v1''then\n  if exists(select 1 from app.native_optional_final_award_sets_v2 where tournament_id=new.tournament_id)then raise exception''optional_final_award_liability_exists'';end if;\n elsif exists(select 1 from app.native_optional_final_award_sets_v2 where tournament_id=new.tournament_id and event_id=new.event_id)then raise exception''optional_final_award_liability_exists'';end if;\n return new;\nend$function$\n","postgres",["search_path=\"\""],["postgres=X/postgres"]],["aa_whole_five_new_awards_v1","O","CREATE TRIGGER aa_whole_five_new_awards_v1 BEFORE INSERT ON app.standard_singles_settlement_final_versions FOR EACH ROW EXECUTE FUNCTION app.require_whole_five_new_awards_v1()","CREATE OR REPLACE FUNCTION app.require_whole_five_new_awards_v1()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare record_json jsonb:=to_jsonb(new);snapshot jsonb;obligations jsonb;amount numeric;isvoid boolean;payout uuid;pv integer;kind text;begin\n case tg_table_name\n when ''standard_singles_settlement_placements''then amount:=new.prize_amount_minor;\n when ''standard_singles_settlement_awards''then amount:=new.amount_minor;\n when ''event_settlement_drafts_v5''then perform app.assert_whole_five_award_array_v1(new.request_payload->''prizeClaims'',''amountMinor'');\n when ''event_settlement_finals_v2''then\n  select d.request_payload into snapshot from app.event_settlement_drafts_v5 d where d.id=new.draft_id and d.tournament_id=new.tournament_id and d.event_id=new.event_id;\n  perform app.assert_whole_five_award_array_v1(snapshot->''prizeClaims'',''amountMinor'');\n when ''standard_singles_settlement_final_versions''then perform app.assert_whole_five_standard_draft_v1(new.settlement_draft_id,new.tournament_id,new.event_id);\n when ''q_accounting_drafts_v6''then\n  perform app.assert_whole_five_award_array_v1(new.source_manifest->''regularSchedule''->''awards'',''totalAwardMinor'');\n  select q.obligations into obligations from app.q_obligation_reviews_v2 q where q.id=new.q_review_id and q.tournament_id=new.tournament_id and q.event_id=new.event_id;\n  perform app.assert_whole_five_q_awards_v1(obligations);\n when ''q_accounting_finals_v6''then\n  select d.source_manifest,q.obligations into snapshot,obligations from app.q_accounting_drafts_v6 d join app.q_obligation_reviews_v2 q on q.id=d.q_review_id where d.id=new.draft_id and d.tournament_id=new.tournament_id and d.event_id=new.event_id;\n  perform app.assert_whole_five_award_array_v1(snapshot->''regularSchedule''->''awards'',''totalAwardMinor'');perform app.assert_whole_five_q_awards_v1(obligations);\n when ''no_q_accounting_drafts_v7''then perform app.assert_whole_five_award_array_v1(new.source_manifest->''regularSchedule''->''awards'',''totalAwardMinor'');\n when ''no_q_accounting_finals_v7''then\n  select d.source_manifest into snapshot from app.no_q_accounting_drafts_v7 d where d.id=new.draft_id and d.tournament_id=new.tournament_id and d.event_id=new.event_id;\n  perform app.assert_whole_five_award_array_v1(snapshot->''regularSchedule''->''awards'',''totalAwardMinor'');\n when ''prize_accounting_drafts_v8''then\n  perform app.assert_whole_five_award_array_v1(new.awards,''totalAwardMinor'');\n  if new.source_manifest->''qReview''is not null and new.source_manifest->''qReview''<>''null''::jsonb then perform app.assert_whole_five_q_awards_v1(new.source_manifest->''qReview''->''obligations'');end if;\n when ''prize_accounting_finals_v8''then\n  select to_jsonb(d)into snapshot from app.prize_accounting_drafts_v8 d where d.id=new.draft_id and d.tournament_id=new.tournament_id and d.event_id=new.event_id;\n  perform app.assert_whole_five_award_array_v1(snapshot->''awards'',''totalAwardMinor'');\n  if snapshot->''source_manifest''->''qReview''is not null and snapshot->''source_manifest''->''qReview''<>''null''::jsonb then perform app.assert_whole_five_q_awards_v1(snapshot->''source_manifest''->''qReview''->''obligations'');end if;\n when ''q_obligation_reviews_v1'',''q_obligation_reviews_v2''then perform app.assert_whole_five_q_awards_v1(new.obligations);\n when ''event_side_pool_policy_versions''then perform app.assert_whole_five_award_array_v1(new.posted_payout_schedule,''amountMinor'');\n when ''event_side_pool_payout_versions'',''event_side_pool_team_payout_versions''then\n  if not new.voided then amount:=new.amount_minor;end if;\n when ''event_side_pool_payout_reviews'',''event_side_pool_payout_review_versions''then\n  if new.approved then\n   payout:=(record_json->>''payout_id'')::uuid;kind:=record_json->>''beneficiary_kind'';pv:=(record_json->>''payout_version'')::integ